-- ── Checklist ──
-- CHECKLIST_ITEMS cites 0199a002-0000-7000-8000-000000000072 = FIRST_RIGHT_OF_REFUSAL
-- CHECKLIST_ITEMS cites 0199a002-0000-7000-8000-000000000073 = SALE_OF_HOME
INSERT INTO template_clause (uuid, section, ordinal, clause_key, title, body, parent, variant_of, numbered, requires_next, style, condition_field, condition_values, required, statute_ref, note, created_by) VALUES
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000001', '0199a001-0000-7000-8000-000000000001', 10, 'CHECKLIST_HEADER', NULL,
                                                                                                                                                                                                                   E'{{property.community_name}}',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000002', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000002', '0199a001-0000-7000-8000-000000000001', 20, 'CHECKLIST_ITEMS', NULL,
                                                                                                                                                                                                                   E'- Everyone 18 years of age and older must fill out a screening application and be approved by the Landlord/agent of the community.\n- If the screening application is conditionally approved or denied, the applicant will be notified by adverse action letter.\n- If approved, the applicant must sign all the appropriate documents.\n- All necessary repairs to the home or lot must be done within <rule w="5"> days of signing the lease, unless otherwise agreed upon. This is a case-by-case matter.\n- Tenant(s) agrees to and signs the Lease/Rental Agreement.\n- Tenant(s) agrees to the Rules and Regulations.\n- Tenant(s) agrees to the Pet Agreement or the Service/Assistance Animal Addendum (if disabled).\n- Tenant(s) agrees to the Vehicle Agreement.\n- Tenant(s) agrees to the Septic Agreement (if applicable).\n- Tenant(s) agrees not to have trampolines.\n- Tenant(s) agrees not to have outdoor activity structures.\n- Tenant(s) agrees not to have a swimming pool larger than 20 gallons.\n- Tenant(s) agrees not to have any campers, boats, fifth wheels, trailers, snowmobiles, ATVs, or vehicles larger than 1 ton of any kind.\n- Tenant(s) agrees not to have any additional RVs beyond one mobile dwelling (includes mobile homes and RVs).\n- Tenant(s) agrees to notify the Landlord/agent of any intent to sell a home, as stated in sections {{ref:0199a002-0000-7000-8000-000000000072}} and {{ref:0199a002-0000-7000-8000-000000000073}} of the Rental/Lease Agreement.\n- Tenant(s) agrees to continuously maintain home and space appearance as stated in the Community Rules and Regulations.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000003', '0199a001-0000-7000-8000-000000000001', 30, 'CHECKLIST_SIGNATURE', NULL,
                                                                                                                                                                                                                   E'UNDERSTOOD AND AGREED TO this <rule w="6"> day of <rule w="18">, {{instrument.execution_year}}, as signed below.\n\n{{#each tenancy.signers}}<rule w="42">\n{{signer.name}}, Tenant\n\n{{/each}}<rule w="42">\nOwner/Agent for {{landlord.name}}',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000004', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002');


