-- TERM_TERMINATE cites 0199a002-0000-7000-8000-000000000021 = RENT_AMOUNT_SINGLE
-- LATE_CHARGES_PERCENT cites 0199a002-0000-7000-8000-000000000021 = RENT_AMOUNT_SINGLE
-- HOLDING_OVER cites 0199a002-0000-7000-8000-000000000015 = TERM_AUTO_RENEW
-- SALE_OF_HOME_D cites 0199a002-0000-7000-8000-000000000074 = SALE_OF_HOME_A
INSERT INTO template_clause (uuid, section, ordinal, clause_key, title, body, parent, variant_of, numbered, requires_next, style, condition_field, condition_values, required, statute_ref, note, created_by) VALUES
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000012', '0199a001-0000-7000-8000-000000000003', 10, 'LEASE_HEADER', NULL,
                                                                                                                                                                                                                   E'{{property.community_name}}',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000002', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000013', '0199a001-0000-7000-8000-000000000003', 20, 'LEASE_PARTIES', NULL,
                                                                                                                                                                                                                   E'THIS AGREEMENT is made and entered into between <b>{{property.community_name}}</b>, located at <u>{{property.physical_address}}, {{property.city}}, {{property.state}} {{property.zip}}</u> (hereinafter called "Landlord"), and <b>{{tenancy.tenant_names}}</b>, the tenant(s)/owner(s) of the manufactured home (hereinafter called "Tenant").',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000014', '0199a001-0000-7000-8000-000000000003', 30, 'DEMISED_PREMISES', 'Demised Premises',
                                                                                                                                                                                                                   E'Landlord leases to Tenant, and Tenant leases from Landlord, manufactured home <b>Lot # {{lot.lot_number}}</b> in <b>{{property.community_name}}</b> for the purpose of residing in a manufactured home for residential purposes only.\n\nTenant''s mailing address, if other than Lot # {{lot.lot_number}}: <rule w="50">',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000015', '0199a001-0000-7000-8000-000000000003', 40, 'TERM_AUTO_RENEW', 'Term and Renewal',
                                                                                                                                                                                                                   E'The term of this agreement is <b>{{instrument.term_months_in_words}} ({{instrument.term_months}}) months</b>, beginning on <b>{{instrument.term_start}}</b> and ending on <b>{{instrument.term_end}}</b>, at the rent stated in Section {{ref:0199a002-0000-7000-8000-000000000021}}. The anniversary date of this agreement is <b>{{instrument.anniversary}}</b> of each year. Upon expiration, this agreement renews automatically for successive terms of twelve (12) months, each beginning on the anniversary date, unless Tenant gives Landlord written notice of Tenant''s intent not to renew at least three (3) months before the end of the then-current term, or the tenancy is terminated as provided by RCW 59.20.080.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, 'instrument.on_expiry', ARRAY['AUTO_RENEW'], TRUE, 'RCW 59.20.090', 'New wording (the 2024 packet had no dates) -- confirm the renewal sentence against RCW 59.20.090 before use', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000016', '0199a001-0000-7000-8000-000000000003', 50, 'TERM_MONTH_TO_MONTH', 'Term and Renewal',
                                                                                                                                                                                                                   E'The term of this agreement is <b>{{instrument.term_months_in_words}} ({{instrument.term_months}}) months</b>, beginning on <b>{{instrument.term_start}}</b> and ending on <b>{{instrument.term_end}}</b>, at the rent stated in Section {{ref:0199a002-0000-7000-8000-000000000021}}. The anniversary date of this agreement is <b>{{instrument.anniversary}}</b> of each year. Upon expiration, and as permitted by Tenant''s written waiver of the right to a one-year term, the tenancy continues from month to month on the same terms until terminated as provided in this agreement and RCW 59.20.',
                                                                                                                                                                                                                   NULL, '0199a002-0000-7000-8000-000000000015', TRUE, NULL, NULL, 'instrument.on_expiry', ARRAY['MONTH_TO_MONTH'], TRUE, 'RCW 59.20.090', 'New wording (the 2024 packet had no dates) -- confirm the renewal sentence against RCW 59.20.090 before use', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000017', '0199a001-0000-7000-8000-000000000003', 60, 'TERM_TERMINATE', 'Term and Renewal',
                                                                                                                                                                                                                   E'The term of this agreement is <b>{{instrument.term_months_in_words}} ({{instrument.term_months}}) months</b>, beginning on <b>{{instrument.term_start}}</b> and ending on <b>{{instrument.term_end}}</b>, at the rent stated in Section {{ref:0199a002-0000-7000-8000-000000000021}}. The anniversary date of this agreement is <b>{{instrument.anniversary}}</b> of each year. This agreement expires at the end of the term and does not renew automatically. Any continued tenancy after {{instrument.term_end}} requires a new written agreement signed by both parties.',
                                                                                                                                                                                                                   NULL, '0199a002-0000-7000-8000-000000000015', TRUE, NULL, NULL, 'instrument.on_expiry', ARRAY['TERMINATE'], TRUE, 'RCW 59.20.090', 'New wording (the 2024 packet had no dates) -- confirm the renewal sentence against RCW 59.20.090 before use', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000018', '0199a001-0000-7000-8000-000000000003', 70, 'FIFTYFIVE_PLUS_RESERVED', 'Reserved for 55+ Community Notification',
                                                                                                                                                                                                                   E'',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000019', '0199a001-0000-7000-8000-000000000003', 80, 'OCCUPANTS', 'Occupants',
                                                                                                                                                                                                                   E'The Tenant shall not give accommodation to any roomers or lodgers, or permit use of the manufactured home for any purpose other than as a residence and as the location of <u>one</u> home and <u>one</u> accessory building. The manufactured home is for the exclusive use of the applicant(s) and their natural or adopted minor children. Any other resident of the home must have the prior approval of the Landlord or its agent, and the Landlord will require a separate screening application. Please list any additional tenants requested below:\n\nName: <rule w="34">  Age: <rule w="5">  Relationship: <rule w="28">\n\nName: <rule w="34">  Age: <rule w="5">  Relationship: <rule w="28">',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000020', '0199a001-0000-7000-8000-000000000003', 90, 'RENT', 'Rent',
                                                                                                                                                                                                                   E'The monthly rent for the above designated lot during the term of this agreement shall be:',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000021', '0199a001-0000-7000-8000-000000000003', 100, 'RENT_AMOUNT_SINGLE', NULL,
                                                                                                                                                                                                                   E'<u><b>{{term.rate_in_words}} ({{term.rate}})</b></u> per month for the balance of the lease agreement, payable on or before the <b>{{term.payment_due_day}} day of each month</b> during the term of this lease.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', NULL, TRUE, NULL, NULL, 'term.rent_schedule_type', ARRAY['SINGLE'], TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000022', '0199a001-0000-7000-8000-000000000003', 110, 'RENT_AMOUNT_SCHEDULED', NULL,
                                                                                                                                                                                                                   E'The monthly rent for each period of the term, payable on or before the <b>{{term.payment_due_day}} day of each month</b>, is:\n\n| Period | Monthly rent |\n{{#each term.rent_schedule}}| {{rent_step.period}} | {{rent_step.rate}} |\n{{/each}}',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', '0199a002-0000-7000-8000-000000000021', TRUE, NULL, NULL, 'term.rent_schedule_type', ARRAY['SCHEDULED'], TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000023', '0199a001-0000-7000-8000-000000000003', 120, 'RENT_HISTORY', NULL,
                                                                                                                                                                                                                   E'| Historical rents | {{lot.rent_history_year_1}} | {{lot.rent_history_year_2}} | {{lot.rent_history_year_3}} | {{lot.rent_history_year_4}} | {{lot.rent_history_year_5}} |\n| Monthly lot rent | {{lot.rent_history_rate_1}} | {{lot.rent_history_rate_2}} | {{lot.rent_history_rate_3}} | {{lot.rent_history_rate_4}} | {{lot.rent_history_rate_5}} |',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20.060', 'The five-year disclosure: each figure is the highest rent charged for this lot that year', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000024', '0199a001-0000-7000-8000-000000000003', 130, 'RENT_INCREASE', NULL,
                                                                                                                                                                                                                   E'Landlord, at its sole option, may increase the monthly rent upon expiration of the original term of this agreement by serving Tenant written notice three (3) months before the effective date of the increase.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.090', 'Confirm the notice period against the current RCW 59.20.090 before use', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000025', '0199a001-0000-7000-8000-000000000003', 140, 'PAYMENT_REMITTANCE', NULL,
                                                                                                                                                                                                                   E'Rent and all additional payments are to be made by check or money order payable to <b>{{property.payable_to}}</b> and may be mailed to <b>{{property.remittance_address}}</b>, or placed in the <b>24-hour/7-day DROP BOX</b> available in the community. All payments must be received in the office by <b>midnight</b> on the <b>{{term.late_after_day}}</b> of the month, unless otherwise agreed upon through an approved reasonable accommodation request.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000026', '0199a001-0000-7000-8000-000000000003', 150, 'LATE_CHARGES_PERCENT', 'Late Charges',
                                                                                                                                                                                                                   E'Tenant agrees that if the full rent, fees, and other charges are not received in our office by <b>midnight</b> of the <b>{{term.late_after_day}}</b> day of each month, Tenant shall pay <b>{{term.late_fee_percent_in_words}} ({{term.late_fee_percent}}) of the monthly lot rent in Section {{ref:0199a002-0000-7000-8000-000000000021}}</b> as a late fee, unless otherwise defined by local governance, in which case the more restrictive late fee will take precedence. In the event that payment is not received in full, a fourteen-day notice to pay rent and/or other charges, or such other notice as the law requires (RCW 59.20.080), will be served on the Tenant. Any payment received will first be applied to current rent due, then to current late fees, current utilities or other charges, and then to any late fees, utility and tax fees, meter fees, pet rent, mobile home payments, mobile home payment late fees, personal property taxes, attorney fees, legal fees, damages, insurance, or any other outstanding fees. Any balance, plus the late fees, then becomes the remaining rent balance due.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', NULL, FALSE, NULL, NULL, 'term.late_fee_method', ARRAY['PERCENT_OF_RENT'], FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000027', '0199a001-0000-7000-8000-000000000003', 160, 'LATE_CHARGES_FLAT', 'Late Charges',
                                                                                                                                                                                                                   E'Tenant agrees that if the full rent, fees, and other charges are not received in our office by <b>midnight</b> of the <b>{{term.late_after_day}}</b> day of each month, Tenant shall pay <b>{{term.late_fee_amount_in_words}} ({{term.late_fee_amount}})</b> as a late fee, unless otherwise defined by local governance, in which case the more restrictive late fee will take precedence. In the event that payment is not received in full, a fourteen-day notice to pay rent and/or other charges, or such other notice as the law requires (RCW 59.20.080), will be served on the Tenant. Any payment received will first be applied to current rent due, then to current late fees, current utilities or other charges, and then to any late fees, utility and tax fees, meter fees, pet rent, mobile home payments, mobile home payment late fees, personal property taxes, attorney fees, legal fees, damages, insurance, or any other outstanding fees. Any balance, plus the late fees, then becomes the remaining rent balance due.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', '0199a002-0000-7000-8000-000000000026', FALSE, NULL, NULL, 'term.late_fee_method', ARRAY['FLAT'], FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000028', '0199a001-0000-7000-8000-000000000003', 170, 'LATE_CHARGES_NONE', 'Late Payment',
                                                                                                                                                                                                                   E'No late fee is charged under this agreement. In the event that payment is not received in full, a fourteen-day notice to pay rent and/or other charges, or such other notice as the law requires (RCW 59.20.080), will be served on the Tenant. Any payment received will first be applied to current rent due, then to current late fees, current utilities or other charges, and then to any late fees, utility and tax fees, meter fees, pet rent, mobile home payments, mobile home payment late fees, personal property taxes, attorney fees, legal fees, damages, insurance, or any other outstanding fees. Any balance, plus the late fees, then becomes the remaining rent balance due.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', '0199a002-0000-7000-8000-000000000026', FALSE, NULL, NULL, 'term.late_fee_method', ARRAY['NONE'], FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000029', '0199a001-0000-7000-8000-000000000003', 180, 'PAYMENT_ACCOMMODATION', NULL,
                                                                                                                                                                                                                   E'If your situation requires an alternative payment date, you may request an accommodation by filling out the attached form and emailing it to {{landlord.compliance_email}} or mailing it to <b>{{property.community_name}}</b>, {{landlord.address}}.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000020', NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000030', '0199a001-0000-7000-8000-000000000003', 190, 'NSF_BANK_OR_FLAT', 'Returned Checks',
                                                                                                                                                                                                                   E'Returned checks, for whatever reason, shall be assessed a charge of {{term.nsf_fee_amount_in_words}} ({{term.nsf_fee_amount}}), or as charged by the financial institution, whichever is greater, in addition to any late charge as set forth above. The date of payment by Tenant''s bank will be considered the payment date for determining any late charge after a returned check. All late charges shall become a part of the rent due for that period. Per RCW 59.20.134, if a personal check is returned for any reason, personal checks will no longer be accepted.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, 'term.nsf_fee_method', ARRAY['BANK_OR_FLAT'], FALSE, 'RCW 59.20.134', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000031', '0199a001-0000-7000-8000-000000000003', 200, 'NSF_FLAT', 'Returned Checks',
                                                                                                                                                                                                                   E'Returned checks, for whatever reason, shall be assessed a charge of {{term.nsf_fee_amount_in_words}} ({{term.nsf_fee_amount}}), in addition to any late charge as set forth above. The date of payment by Tenant''s bank will be considered the payment date for determining any late charge after a returned check. All late charges shall become a part of the rent due for that period. Per RCW 59.20.134, if a personal check is returned for any reason, personal checks will no longer be accepted.',
                                                                                                                                                                                                                   NULL, '0199a002-0000-7000-8000-000000000030', TRUE, NULL, NULL, 'term.nsf_fee_method', ARRAY['FLAT'], FALSE, 'RCW 59.20.134', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000032', '0199a001-0000-7000-8000-000000000003', 210, 'NSF_NONE', 'Returned Checks',
                                                                                                                                                                                                                   E'No fee is charged for a returned check; the payment is treated as not received. Per RCW 59.20.134, if a personal check is returned for any reason, personal checks will no longer be accepted.',
                                                                                                                                                                                                                   NULL, '0199a002-0000-7000-8000-000000000030', TRUE, NULL, NULL, 'term.nsf_fee_method', ARRAY['NONE'], FALSE, 'RCW 59.20.134', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000033', '0199a001-0000-7000-8000-000000000003', 220, 'SECURITY_DEPOSIT', 'Security Deposit',
                                                                                                                                                                                                                   E'Tenant shall pay a security deposit of {{term.security_deposit_in_words}} ({{term.security_deposit}}) upon signing this agreement. The deposit will be held and accounted for as required by law and returned, less any lawful deductions itemized in writing, after Tenant vacates the lot.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, 'term.security_deposit_method', ARRAY['FLAT', 'MULTIPLE_OF_RENT'], FALSE, NULL, 'New wording, not from the 2024 packet -- have it reviewed before use', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000034', '0199a001-0000-7000-8000-000000000003', 230, 'ADDITIONAL_CHARGES', 'Additional Charges',
                                                                                                                                                                                                                   E'In addition to the monthly rent and other fees or charges specified in this agreement, there may be such additional charges as are set forth in the community rules. The monthly rent may be increased on a pro rata basis to cover any increase in the Owner''s real property taxes for the community, or in utility assessments or charges, over the base taxes or utility assessments or charges in the year during which this agreement takes effect. A pro rata reduction in the rent will also be made in the event of a reduction in the property taxes or utility assessments or charges. Charges may include, but are not limited to, services rendered or contracted for, service of notification, and non-compliance with the Community Rules or Lease Agreement. Notice shall be given to Tenant seven (7) days in advance of service, and any additional charges shall be given to Tenant on an itemized bill and become a part of the balance due.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000035', '0199a001-0000-7000-8000-000000000003', 240, 'POSSESSION', 'Possession',
                                                                                                                                                                                                                   E'In the event that Landlord is not able to deliver possession at the commencement of the term, Landlord shall not be liable for any damages caused thereby, nor shall this rental agreement be voidable, but Tenant shall not be liable for rent until Landlord can deliver possession. Possession shall be delivered on or after the commencement of the term, when the lot is ready to be occupied by Tenant.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000036', '0199a001-0000-7000-8000-000000000003', 250, 'UTILITIES', 'Utilities and Service',
                                                                                                                                                                                                                   E'Landlord has provided a connection point for water, sanitary sewer, electricity, and telephone service used at the lot. <b>The Tenant(s) are responsible for all utility transmission lines and connection points attached to and coming from the home, up to the Landlord-supplied water valve, electric panel or pedestal, and sewer or septic connection point. The Landlord is only responsible for maintenance up to and including the Landlord-provided utility connections.</b> Tenant shall bear the cost of making connections to said services. Landlord shall not be liable for interruptions in said services which are beyond Landlord''s reasonable control. <b>Landlord shall promptly repair and maintain utilities within its responsible areas to prevent service interruptions.</b>',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000037', '0199a001-0000-7000-8000-000000000003', 260, 'UTILITIES_TENANT_PAYS', NULL,
                                                                                                                                                                                                                   E'Except for any utility stated below to be included in the rent, Tenant shall, in addition to the monthly rent, pay for all public utilities supplied to the lot during the existence of this rental agreement, whether billed by the provider directly or by Landlord as stated below. Utility increases will be passed through to Tenant as they are raised or lowered by the utility company. Unless garbage service is provided by Landlord, Tenant is required to contract with a local garbage removal service, and Landlord may request proof of that service from time to time in order to assure compliance.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000038', '0199a001-0000-7000-8000-000000000003', 270, 'UTILITY_WATER_INCLUDED', NULL,
                                                                                                                                                                                                                   E'<b>Water</b> is included in the monthly rent.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, 'term.water_method', ARRAY['INCLUDED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000039', '0199a001-0000-7000-8000-000000000003', 280, 'UTILITY_WATER_FLAT', NULL,
                                                                                                                                                                                                                   E'<b>Water</b> is billed by Landlord at a flat {{term.water_flat_amount}} per month.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000038', FALSE, NULL, NULL, 'term.water_method', ARRAY['FLAT'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000040', '0199a001-0000-7000-8000-000000000003', 290, 'UTILITY_WATER_RUBS', NULL,
                                                                                                                                                                                                                   E'<b>Water</b> is billed by a Ratio Utility Billing System (RUBS): Landlord''s actual water cost is divided evenly among the occupied spaces in the community, and Tenant pays that proportionate share.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000038', FALSE, NULL, NULL, 'term.water_method', ARRAY['RUBS'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000041', '0199a001-0000-7000-8000-000000000003', 300, 'UTILITY_WATER_SUBMETERED', NULL,
                                                                                                                                                                                                                   E'<b>Water</b> is sub-metered. Tenant will be billed separately for use on the meter, plus any utility tax billed by the provider, on the monthly or bi-monthly basis established by the service provider.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000038', FALSE, NULL, NULL, 'term.water_method', ARRAY['SUBMETERED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000042', '0199a001-0000-7000-8000-000000000003', 310, 'UTILITY_SEWER_INCLUDED', NULL,
                                                                                                                                                                                                                   E'<b>Sewer</b> is included in the monthly rent.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, 'term.sewer_method', ARRAY['INCLUDED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000043', '0199a001-0000-7000-8000-000000000003', 320, 'UTILITY_SEWER_FLAT', NULL,
                                                                                                                                                                                                                   E'<b>Sewer</b> is billed by Landlord at a flat {{term.sewer_flat_amount}} per month.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000042', FALSE, NULL, NULL, 'term.sewer_method', ARRAY['FLAT'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000044', '0199a001-0000-7000-8000-000000000003', 330, 'UTILITY_SEWER_RUBS', NULL,
                                                                                                                                                                                                                   E'<b>Sewer</b> is billed by a Ratio Utility Billing System (RUBS): Landlord''s actual sewer cost is divided evenly among the occupied spaces in the community, and Tenant pays that proportionate share.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000042', FALSE, NULL, NULL, 'term.sewer_method', ARRAY['RUBS'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000045', '0199a001-0000-7000-8000-000000000003', 340, 'UTILITY_SEWER_SUBMETERED', NULL,
                                                                                                                                                                                                                   E'<b>Sewer</b> is sub-metered. Tenant will be billed separately for use on the meter, plus any utility tax billed by the provider, on the monthly or bi-monthly basis established by the service provider.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000042', FALSE, NULL, NULL, 'term.sewer_method', ARRAY['SUBMETERED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000046', '0199a001-0000-7000-8000-000000000003', 350, 'UTILITY_POWER_INCLUDED', NULL,
                                                                                                                                                                                                                   E'<b>Electricity</b> is included in the monthly rent.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, 'term.power_method', ARRAY['INCLUDED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000047', '0199a001-0000-7000-8000-000000000003', 360, 'UTILITY_POWER_FLAT', NULL,
                                                                                                                                                                                                                   E'<b>Electricity</b> is billed by Landlord at a flat {{term.power_flat_amount}} per month.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000046', FALSE, NULL, NULL, 'term.power_method', ARRAY['FLAT'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000048', '0199a001-0000-7000-8000-000000000003', 370, 'UTILITY_POWER_RUBS', NULL,
                                                                                                                                                                                                                   E'<b>Electricity</b> is billed by a Ratio Utility Billing System (RUBS): Landlord''s actual electricity cost is divided evenly among the occupied spaces in the community, and Tenant pays that proportionate share.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000046', FALSE, NULL, NULL, 'term.power_method', ARRAY['RUBS'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000049', '0199a001-0000-7000-8000-000000000003', 380, 'UTILITY_POWER_SUBMETERED', NULL,
                                                                                                                                                                                                                   E'<b>Electricity</b> is sub-metered. Tenant will be billed separately for use on the meter, plus any utility tax billed by the provider, on the monthly or bi-monthly basis established by the service provider.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000046', FALSE, NULL, NULL, 'term.power_method', ARRAY['SUBMETERED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000050', '0199a001-0000-7000-8000-000000000003', 390, 'UTILITY_TRASH_INCLUDED', NULL,
                                                                                                                                                                                                                   E'<b>Garbage service</b> is included in the monthly rent.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, 'term.trash_method', ARRAY['INCLUDED'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000051', '0199a001-0000-7000-8000-000000000003', 400, 'UTILITY_TRASH_FLAT', NULL,
                                                                                                                                                                                                                   E'<b>Garbage service</b> is billed by Landlord at a flat {{term.trash_flat_amount}} per month.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000050', FALSE, NULL, NULL, 'term.trash_method', ARRAY['FLAT'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000052', '0199a001-0000-7000-8000-000000000003', 410, 'UTILITY_TRASH_RUBS', NULL,
                                                                                                                                                                                                                   E'<b>Garbage service</b> is billed by a Ratio Utility Billing System (RUBS): Landlord''s actual garbage cost is divided evenly among the occupied spaces in the community, and Tenant pays that proportionate share.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', '0199a002-0000-7000-8000-000000000050', FALSE, NULL, NULL, 'term.trash_method', ARRAY['RUBS'], FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000053', '0199a001-0000-7000-8000-000000000003', 420, 'UTILITIES_ONSITE_LIMITS', NULL,
                                                                                                                                                                                                                   E'Homes with sub-metered water connections served by an <u>Onsite Septic System</u> or <u>Onsite Water System</u> will be limited to <b>nine thousand gallons (9,000 gal) per month.</b> Any tenant water use in excess of this amount on an onsite water system connection will be issued a notice to comply for excess water usage. After three notices to comply within one calendar year, Tenant may be subject to RCW 59.20.080 and termination of the lease agreement. The cost of repairing any tenant-caused damage to the septic system from excessive usage or misuse will be passed on to Tenant.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000054', '0199a001-0000-7000-8000-000000000003', 430, 'SEPTIC_PUMPING', NULL,
                                                                                                                                                                                                                   E'Septic tanks are periodically inspected and pumped by Management approximately once every three years, or as needed. If more frequent pumping is required because of excessive water use (average water use is approximately 240 gallons per home per day) or the other abuses discussed above, the cost of the extra pumping may be charged to the Tenant(s) of that particular system.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000036', NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000055', '0199a001-0000-7000-8000-000000000003', 440, 'DUTIES_OF_TENANT', 'Duties of the Tenant',
                                                                                                                                                                                                                   E'It shall be the duty of Tenant to pay the rent at such times and in such amounts as provided for in this rental agreement or as otherwise provided by law, and to comply with all obligations imposed upon tenants by applicable provisions of all municipal, county, and state codes, statutes, ordinances, and regulations. In addition, Tenant shall:',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.140', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000056', '0199a001-0000-7000-8000-000000000003', 450, 'DUTIES_OF_TENANT_A', NULL,
                                                                                                                                                                                                                   E'Keep the mobile home lot which he or she occupies and uses as clean and sanitary as the conditions of the premises permit.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000057', '0199a001-0000-7000-8000-000000000003', 460, 'DUTIES_OF_TENANT_B', NULL,
                                                                                                                                                                                                                   E'Comply with all applicable federal, state, and local laws, regulations, and ordinances pertaining to the lot, the home located on it, and its appurtenances, and hold Landlord harmless from all fines, penalties, and costs for violations or noncompliance, to the extent allowed by law.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000058', '0199a001-0000-7000-8000-000000000003', 470, 'DUTIES_OF_TENANT_C', NULL,
                                                                                                                                                                                                                   E'Properly dispose of all rubbish, garbage, trash, or other organic or flammable waste in a clean and sanitary manner at reasonable and regular intervals, and assume all costs of extermination and fumigation for any infestation caused by Tenant on the leased premises.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000059', '0199a001-0000-7000-8000-000000000003', 480, 'DUTIES_OF_TENANT_D', NULL,
                                                                                                                                                                                                                   E'Immediately notify the manager of any damage to the community caused by the acts or neglect of Tenant or Tenant''s guests. Unless otherwise agreed, Landlord shall repair the damage and charge Tenant for the repair, which Tenant agrees to pay to Landlord by the next monthly rent due date, or on terms mutually agreed to in writing by Landlord and Tenant.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000060', '0199a001-0000-7000-8000-000000000003', 490, 'DUTIES_OF_TENANT_E', NULL,
                                                                                                                                                                                                                   E'Not intentionally or negligently destroy, deface, damage, impair, or remove any facilities, equipment, furniture, furnishings, fixtures, or appliances provided by Landlord, or permit any member of Tenant''s family, invitees, licensees, or any person acting under Tenant''s control to do so.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000061', '0199a001-0000-7000-8000-000000000003', 500, 'DUTIES_OF_TENANT_F', NULL,
                                                                                                                                                                                                                   E'Not permit a nuisance or common waste, and comply with all community rules and regulations.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000062', '0199a001-0000-7000-8000-000000000003', 510, 'DUTIES_OF_TENANT_G', NULL,
                                                                                                                                                                                                                   E'Not engage in drug-related activities as defined in RCW 59.20.080.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000055', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000063', '0199a001-0000-7000-8000-000000000003', 520, 'COMMUNITY_RULES_NO_FEE', 'Community Rules and Regulations',
                                                                                                                                                                                                                   E'Tenant acknowledges receipt of a copy of the following addenda to this rental agreement: <b>{{packet.addenda}}</b>, which Tenant has read and understands. Tenant agrees to strictly comply with the terms and conditions of those addenda. Tenant further agrees that Landlord may, upon thirty (30) days'' notice, make changes or additions to those addenda deemed necessary for the best interest of the community and its tenants. Violations of the Lease Agreement or the Community Rules and Regulations will be subject to a notice to comply. There will be no fee issued for this notice. After three notices to comply within one calendar year, Tenant may be subject to RCW 59.20.080 and termination of the lease agreement.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, 'term.rule_violation_fee_method', ARRAY['NONE'], TRUE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000064', '0199a001-0000-7000-8000-000000000003', 530, 'COMMUNITY_RULES_FEE', 'Community Rules and Regulations',
                                                                                                                                                                                                                   E'Tenant acknowledges receipt of a copy of the following addenda to this rental agreement: <b>{{packet.addenda}}</b>, which Tenant has read and understands. Tenant agrees to strictly comply with the terms and conditions of those addenda. Tenant further agrees that Landlord may, upon thirty (30) days'' notice, make changes or additions to those addenda deemed necessary for the best interest of the community and its tenants. Violations of the Lease Agreement or the Community Rules and Regulations will be subject to a notice to comply. A fee of {{term.rule_violation_fee_amount}} will be charged for each notice to comply issued. After three notices to comply within one calendar year, Tenant may be subject to RCW 59.20.080 and termination of the lease agreement.',
                                                                                                                                                                                                                   NULL, '0199a002-0000-7000-8000-000000000063', TRUE, NULL, NULL, 'term.rule_violation_fee_method', ARRAY['FLAT'], TRUE, 'RCW 59.20.080', 'The 2024 packet charged no fee -- confirm a per-notice fee is lawful before use', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000065', '0199a001-0000-7000-8000-000000000003', 540, 'COMMUNITY_RULES_AMENDMENTS', NULL,
                                                                                                                                                                                                                   E'Tenants will be provided at least thirty (30) days'' written notice of any new or amended rule. Tenant will have three months to comply with the new or amended rule after the thirty-day notice period. Within that three-month grace period, any violation of the new or amended rule will result in a warning only. Landlord will abide by all codes, statutes, ordinances, and administrative rules applicable to the mobile home park regarding notification periods.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000066', '0199a001-0000-7000-8000-000000000003', 550, 'LANDLORD_IDENTIFICATION', 'Notice/Landlord Identification',
                                                                                                                                                                                                                   E'Any notice required to be served on Tenant at Landlord''s request, and/or any addendum hereto in accordance with the terms of this Rental Agreement or the Community Rules and Regulations, shall be delivered by the manager in writing. {{landlord.name}}, located at the address listed below, may solely act as the agent for the purpose of serving notices and legal process. Any notice required to be served by Tenant upon Landlord in accordance with the terms of this agreement shall be delivered to {{landlord.name}}.\n\n<b>The Landlord is {{landlord.name}}, and the Landlord''s address is {{landlord.address}}.</b>',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20.060', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000067', '0199a001-0000-7000-8000-000000000003', 560, 'PETS', 'Pets',
                                                                                                                                                                                                                   E'Pets are restricted as outlined in the Community Rules and Regulations and the Pet Agreement. Tenant agrees to have no animals of any kind on or at the premises without an approved Pet Agreement/Addendum or an approved reasonable accommodation request. Guests shall not bring any pets, other than service or assistance animals, into the community.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000068', '0199a001-0000-7000-8000-000000000003', 570, 'IMPROVEMENTS', 'Improvements',
                                                                                                                                                                                                                   E'Tenant agrees not to make or permit any construction, alteration, addition, painting, or improvement to the premises, including any storage facilities, without the prior written approval of the Landlord or its agent and all permits required for such an improvement. Replacement exterior materials must be new, painted or weather treated, and intended for outside use.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000069', '0199a001-0000-7000-8000-000000000003', 580, 'VEHICLES_PARKING', 'Vehicles/Parking',
                                                                                                                                                                                                                   E'Refer to the Vehicle Agreement and the Rules and Regulations for all vehicle and parking rules.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000070', '0199a001-0000-7000-8000-000000000003', 590, 'TERMINATION_EVICTION', 'Termination/Eviction',
                                                                                                                                                                                                                   E'This Rental Agreement may be terminated by Landlord, and Tenant may be evicted, in the manner provided by the Manufactured/Mobile Home Landlord-Tenant Act, RCW 59.20.080.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000071', '0199a001-0000-7000-8000-000000000003', 600, 'HOLDING_OVER', 'Holding Over',
                                                                                                                                                                                                                   E'Except where Landlord/agent serves notice of termination on Tenant as provided under RCW 59.20.080, this agreement expires as provided in Section {{ref:0199a002-0000-7000-8000-000000000015}} of this agreement. If Tenant, without the agent''s consent, continues in possession of the lot following the date of termination specified in any notice of termination served on either party, Tenant shall pay the monthly rent, pro-rated on a daily basis, for each day Tenant remains in possession. Possession shall be deemed retained if Tenant''s continued occupancy or actions prevent Landlord from renting the lot to another tenant, such as Tenant''s refusal to vacate, failure to remove personal property, or damage to the lot that renders it temporarily uninhabitable.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000072', '0199a001-0000-7000-8000-000000000003', 610, 'FIRST_RIGHT_OF_REFUSAL', 'First Right of Refusal',
                                                                                                                                                                                                                   E'Landlord''s First Right of Refusal is hereby stricken from this lease agreement. {{landlord.name}} will strictly enforce RCW 59.20.073.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20.073', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000073', '0199a001-0000-7000-8000-000000000003', 620, 'SALE_OF_HOME', 'Sale of Home',
                                                                                                                                                                                                                   E'This Rental Agreement may be assigned for the remainder of its term by Tenant to any person to whom Tenant sells or transfers title to his/her manufactured home, subject to the provisions of RCW 59.20.073, as follows:',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20.073', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000074', '0199a001-0000-7000-8000-000000000003', 630, 'SALE_OF_HOME_A', NULL,
                                                                                                                                                                                                                   E'A tenant who wishes to sell a home within the community shall notify the Landlord/agent in writing of the intent to sell the home at least fifteen (15) days before the intended sale.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000073', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000075', '0199a001-0000-7000-8000-000000000003', 640, 'SALE_OF_HOME_B', NULL,
                                                                                                                                                                                                                   E'The seller must inform the buyer that the buyer must contact the manager and obtain an application, and that application must be processed and approved <u><b>PRIOR TO THE SALE, THE EXCHANGE OF MONEY, OR ANY OCCUPANCY OF THE HOME BY THE BUYER.</b></u>',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000073', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000076', '0199a001-0000-7000-8000-000000000003', 650, 'SALE_OF_HOME_C', NULL,
                                                                                                                                                                                                                   E'The Landlord/agent shall approve or disapprove the assignment of a rental agreement on the same basis that the Landlord/agent approves or disapproves any new tenant, and any disapproval shall be in writing within seven (7) days of receipt of a complete application.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000073', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000077', '0199a001-0000-7000-8000-000000000003', 660, 'SALE_OF_HOME_D', NULL,
                                                                                                                                                                                                                   E'Failure to notify the Landlord/agent in writing as required under subsection {{ref:0199a002-0000-7000-8000-000000000074}} of this section, or failure of the new tenant to make a good-faith attempt to arrange an interview with the Landlord/agent to make application, shall be grounds for disapproval of the transfer.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000073', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000078', '0199a001-0000-7000-8000-000000000003', 670, 'SALE_OF_HOME_E', NULL,
                                                                                                                                                                                                                   E'Transfer of the rental agreement will not be unreasonably withheld. Transfer will be withheld (or denied) if an applicant fails to provide necessary screening documents or fails to respond to reasonable requests based on the results of the background check or other information provided.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000073', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000079', '0199a001-0000-7000-8000-000000000003', 680, 'SALE_OF_HOME_F', NULL,
                                                                                                                                                                                                                   E'Failure to pay any outstanding balance at the time of transfer may result in further legal action against the seller, including pursuing a judgment, garnishment, and attorney''s fees for the entire balance of the lease agreement, up to the time a new lease or assumption is signed.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000073', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000080', '0199a001-0000-7000-8000-000000000003', 690, 'SUBLEASING_ASSIGNMENT', 'Subleasing/Assignment',
                                                                                                                                                                                                                   E'Tenant shall not rent out, sublet, or assign all or any part of his/her manufactured home or lot to another person. Acceptance of rent from a person other than the authorized tenant shall not constitute a waiver of this provision. Tenant shall be the homeowner of the manufactured home.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000081', '0199a001-0000-7000-8000-000000000003', 700, 'PROPERTY_ON_TERMINATION', 'Property',
                                                                                                                                                                                                                   E'Upon termination of this Rental Agreement, Tenant shall remove all of Tenant''s property from the premises, including, without limitation, Tenant''s manufactured home. All other improvements to the lot, except natural lawn, which have been paid for by Tenant shall be the property of Tenant and may be removed or disposed of by Tenant before the termination of this Rental Agreement. Tenant shall in all events restore the lot to substantially the same or better condition than when Tenant, or Tenant''s predecessor in interest, first took possession of the lot. Any property of Tenant affixed to the land, other than Tenant''s manufactured home, which has not been removed by Tenant upon termination of this Rental Agreement shall become the property of Landlord.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000082', '0199a001-0000-7000-8000-000000000003', 710, 'LIABILITY_INDEMNITY', 'Liability and Indemnity',
                                                                                                                                                                                                                   E'Tenant agrees that all of his/her personal property in the community, including Tenant''s manufactured home, shall be at the risk of Tenant to the extent allowed by law. Tenant further agrees that Landlord shall not be liable on account of any loss or damage sustained by the action of any third party, fire, theft, water, the elements, or for loss of any property from any cause from said lot or any other part of the community, nor shall Landlord be liable for any injury to Tenant, his/her family, guests, employees, or any person entering the community or the property of which the community is a part, unless caused by the sole negligence of Landlord, to the extent allowed by law. Tenant hereby waives all such claims and agrees to indemnify Landlord/agent against any such loss, damage, liability, or expense incurred by Landlord in connection therewith, to the extent allowed by law. Tenant is advised to purchase suitable insurance to cover damage to the home from natural causes, such as storms, falling branches, and trees, as well as other types of hazards.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000083', '0199a001-0000-7000-8000-000000000003', 720, 'MONTH_TO_MONTH_NOTICE', 'Month-to-Month Notice',
                                                                                                                                                                                                                   E'In the event that the tenancy is on a month-to-month basis, Tenant agrees to give Landlord thirty (30) days'' written notice of his/her intent to vacate the property.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000084', '0199a001-0000-7000-8000-000000000003', 730, 'ZONING', 'Zoning',
                                                                                                                                                                                                                   E'The current zoning for <b>{{property.community_name}}</b> is {{property.zoning}}.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20.060', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000085', '0199a001-0000-7000-8000-000000000003', 740, 'CONDEMNATION', 'Condemnation – Eminent Domain',
                                                                                                                                                                                                                   E'In the event the whole or any part of the manufactured home lot(s) is taken by any competent authority for a public or quasi-public use or purpose, the term of this Rental Agreement shall cease and terminate from the date when possession of the part so taken is required for such use or purpose. All damages awarded for such taking shall belong to and be the property of Landlord.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000086', '0199a001-0000-7000-8000-000000000003', 750, 'EMERGENCY_FORWARDING', 'Emergency and Forwarding Address',
                                                                                                                                                                                                                   E'In the event of an emergency or abandonment of Tenant''s manufactured home, the name and address of the person you would like contacted, and who would most likely know of Tenant''s whereabouts, is:\n\n<rule w="80">',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000087', '0199a001-0000-7000-8000-000000000003', 760, 'ABANDONMENT', 'Abandonment',
                                                                                                                                                                                                                   E'Abandonment occurs if the rent and related obligations have not been paid for the preceding sixty (60) days and Landlord reasonably believes, based upon circumstances, words, and actions, that the tenant(s) have left the home on the lot. If the manager finds that the premises have been abandoned, the manager will conspicuously post a notice of abandonment outside the premises, and if no response is received from Tenant within <u><b>10 days</b></u>, Tenant will be considered in default of this Lease, and the manager or the manager''s agents may immediately, or at any time thereafter, retake the leased lot and terminate this Lease without notice to Tenant. Any personal property left behind will be handled in accordance with state law regarding abandoned property, and Tenant will be provided a reasonable opportunity to reclaim their belongings.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000088', '0199a001-0000-7000-8000-000000000003', 770, 'SECURED_PARTY', 'Secured Party',
                                                                                                                                                                                                                   E'The name, address, phone number, and account number of each lending institution (or other entity or person) that has a secured interest in Tenant''s manufactured home is:\n\n<rule w="80">',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000089', '0199a001-0000-7000-8000-000000000003', 780, 'MEDIATION', 'Mediation',
                                                                                                                                                                                                                   E'In the event Tenant fails to participate in mediation as required by RCW 59.20.080(2), Landlord shall be entitled to recover from Tenant all fees and costs incurred in the mediation process.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.080(2)', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000090', '0199a001-0000-7000-8000-000000000003', 790, 'ATTORNEYS_FEES', 'Attorney’s Fees',
                                                                                                                                                                                                                   E'In any action arising out of this Rental Agreement, including eviction, the prevailing party shall be entitled to their attorney''s fees and costs.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000091', '0199a001-0000-7000-8000-000000000003', 800, 'SEVERABILITY', 'Severability',
                                                                                                                                                                                                                   E'This agreement is intended to comply with all applicable local, state, and federal laws. If any term, covenant, or provision of this Rental Agreement is held by a court of competent jurisdiction to be invalid, void, or unenforceable, the remainder of the provisions herein shall remain in full force and effect.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000092', '0199a001-0000-7000-8000-000000000003', 810, 'ENFORCEMENT', 'Enforcement',
                                                                                                                                                                                                                   E'Failure of the Owner to insist upon the strict performance of the terms, covenants, agreements, and conditions herein contained, or any of them, shall not constitute or be construed as a waiver or relinquishment of Landlord''s right thereafter to enforce any such term, covenant, agreement, or condition, but the same shall continue in full force and effect. Landlord''s acceptance of any rent after Tenant breaches this agreement shall not waive Landlord''s rights or remedies created by Tenant''s breach.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000093', '0199a001-0000-7000-8000-000000000003', 820, 'HEIRS_SUCCESSORS', 'Heirs and Successors',
                                                                                                                                                                                                                   E'Subject to the provisions herein pertaining to assignment and subletting, the covenants and agreements of this Rental Agreement shall be binding upon the heirs, legal representatives, successors, and assigns of any and all of the parties herein.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000094', '0199a001-0000-7000-8000-000000000003', 830, 'HAZARDOUS_SUBSTANCES', 'Hazardous Substances',
                                                                                                                                                                                                                   E'Any product containing hazardous substances, as defined by RCW 70A.305.020, including but not limited to petroleum products, oil, gasoline, paints, solvents, fertilizers, pesticides, and herbicides, shall be stored in closed containers that are in good condition and kept in a manner that prevents leaking. Tenant shall comply with all local, state, and federal laws regarding hazardous substances AND SHALL NOT ALLOW THE DISPOSAL OF ANY HAZARDOUS SUBSTANCE ON THE PREMISES or within the community, in any storm drain, or into the sewage system. Tenant agrees to immediately clean up any spill of any hazardous substance and notify Landlord or its agent of the circumstances surrounding the spill and the action taken. Tenant agrees to indemnify and hold Landlord harmless from any and all liability arising out of any release of a hazardous substance caused by Tenant or by breach of this agreement.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 70A.305.020', 'The 2024 packet cited RCW 70.105D.020, since recodified as RCW 70A.305.020', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000095', '0199a001-0000-7000-8000-000000000003', 840, 'LANDLORD_ACCESS', 'Landlord Access to Lot Space',
                                                                                                                                                                                                                   E'Tenant agrees that the Landlord/agent or its contracted workers have access to the lot space without notice in emergencies. The Landlord/agent may enter the lot space without notice at a reasonable time for the purpose of emergency utility maintenance or utility meter reading. The Landlord/agent shall make a reasonable effort to notify Tenant before entering the land on which a mobile home, manufactured home, or park model is located.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000096', '0199a001-0000-7000-8000-000000000003', 850, 'ADDENDA', 'Addenda',
                                                                                                                                                                                                                   E'Any addendum or amendment to this agreement shall be in writing, with thirty (30) days'' written notice unless a different notice period is required by law. The following addenda are attached to and hereby become part of this Lease: <b>{{packet.addenda}}</b>.\n\nAlso attached, where checked:  <rule w="5"> "A" – Lot Description    <rule w="5"> Waiver of One-Year Lease',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000097', '0199a001-0000-7000-8000-000000000003', 860, 'ENTIRE_AGREEMENT', NULL,
                                                                                                                                                                                                                   E'This Lease, with any attached addenda, constitutes the sole and only agreement between Landlord and Tenant and supersedes any prior agreement, either oral or written, between Landlord and Tenant. No subsequent oral agreement between Landlord or Landlord''s agent and Tenant shall have any bearing whatsoever on this Lease Agreement.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000098', '0199a001-0000-7000-8000-000000000003', 870, 'PARK_CLOSURE_STATEMENT', NULL,
                                                                                                                                                                                                                   E'RCW 59.20.060 requires the following statement to be included in this Rental Agreement:\n\nThe park may be sold or otherwise transferred at any time with the result that subsequent Landlords may close the mobile home park, or that the landlord may close the park at any time after the required closure notice as provided in RCW 59.20.080.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, '0199a002-0000-7000-8000-000000000099', '0199a003-0000-7000-8000-000000000001', NULL, NULL, TRUE, 'RCW 59.20.060', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000099', '0199a001-0000-7000-8000-000000000003', 880, 'LEASE_SIGNATURE', NULL,
                                                                                                                                                                                                                   E'UNDERSTOOD AND AGREED TO this <rule w="6"> day of <rule w="18">, {{instrument.execution_year}}, as signed below.\n\n{{#each tenancy.signers}}<rule w="42">\n{{signer.name}}, Tenant\n\n{{/each}}<rule w="42">\nOwner/Agent for {{landlord.name}}',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000004', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002');


-- ── Rules and Regulations ──
-- RULES_SITE_REQUIREMENTS_C cites 0199a002-0000-7000-8000-000000000120 = RULES_LANDSCAPING
-- RULES_STORAGE cites 0199a002-0000-7000-8000-000000000122 = RULES_APPEARANCE_A
INSERT INTO template_clause (uuid, section, ordinal, clause_key, title, body, parent, variant_of, numbered, requires_next, style, condition_field, condition_values, required, statute_ref, note, created_by) VALUES
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000100', '0199a001-0000-7000-8000-000000000004', 10, 'RULES_HEADER', NULL,
                                                                                                                                                                                                                   E'{{property.community_name}}',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000002', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000101', '0199a001-0000-7000-8000-000000000004', 20, 'RULES_PREAMBLE', NULL,
                                                                                                                                                                                                                   E'The following rules apply to all manufactured homes in the park and are expressly made part of the Rental Agreement between the Tenant(s), <u><b>{{tenancy.tenant_names}}</b></u>, and the Park.\n\n<u><b>{{property.community_name}}</b></u> is privately owned land, and no person shall live in a mobile/manufactured home on Park property without the prior permission and written approval of the Landlord/agent.\n\nEquipment and apparatus on these grounds are solely for the convenience of the residents, and all persons using them do so at their own risk. The Landlord or its agent will not be responsible for accidents, injuries, or loss of property by fire, theft, wind, floods, or any act beyond the Landlord''s control, to the extent allowed by law.\n\nResidents, family members, occupants of the home, and guests of residents must all abide by these Park Rules and Regulations, and the Landlord reserves the right to evict any resident who does not, and to refuse access to any nonresident or guest whom the Landlord or its agent observes violating these rules:',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000102', '0199a001-0000-7000-8000-000000000004', 30, 'RULES_SIGNED_AGREEMENT', NULL,
                                                                                                                                                                                                                   E'In accordance with the Washington State Manufactured/Mobile Home Landlord-Tenant Act, all residents must complete and sign the Rental Agreement before taking occupancy in the park. Acceptance of rent shall not constitute a waiver of this provision.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, TRUE, 'RCW 59.20', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000103', '0199a001-0000-7000-8000-000000000004', 40, 'RULES_NO_SUBLET', NULL,
                                                                                                                                                                                                                   E'Mobile/manufactured homes may not be rented, loaned, or used for any purpose other than that granted in the original application for lot space in the park. Subletting, assignment, or use as transient accommodation is strictly prohibited.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000104', '0199a001-0000-7000-8000-000000000004', 50, 'RULES_SITE_REQUIREMENTS', 'Site Requirements',
                                                                                                                                                                                                                   E'',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000105', '0199a001-0000-7000-8000-000000000004', 60, 'RULES_SITE_REQUIREMENTS_A', NULL,
                                                                                                                                                                                                                   E'Tenant agrees to maintain the lot/space to a high-quality standard, normal wear and tear expected, and, upon agreeing to lease the space, to bring the lot space up to the park''s current standard as determined by the Landlord.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000104', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000106', '0199a001-0000-7000-8000-000000000004', 70, 'RULES_SITE_REQUIREMENTS_B', NULL,
                                                                                                                                                                                                                   E'Each lot/space has underground utilities available. It shall be the responsibility of Tenant and/or the home installer to connect to them as they exist. Such installations shall be made in accordance with the applicable regulations and building codes in effect. Only licensed contractors shall dig trenches or make electrical connections, after verification of services and boundaries.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000104', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000107', '0199a001-0000-7000-8000-000000000004', 80, 'RULES_SITE_REQUIREMENTS_C', NULL,
                                                                                                                                                                                                                   E'New installations shall require landscaping as provided in rule {{ref:0199a002-0000-7000-8000-000000000120}}, at the resident''s expense, within sixty (60) days of the home''s arrival at the park. Plans for each lot must have the prior approval of the Landlord. <b>NOTICE:</b> If Tenant fails to complete landscaping within sixty (60) days, Landlord shall have the right to hire a professional landscaper, for up to $2,000.00, to complete the site. Any reasonable sum spent on landscaping will be charged to Tenant.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000104', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000108', '0199a001-0000-7000-8000-000000000004', 90, 'RULES_SITE_REQUIREMENTS_D', NULL,
                                                                                                                                                                                                                   E'Perimeter landscaping along the fence will be maintained by Tenant as part of their overall landscaping.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000104', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000109', '0199a001-0000-7000-8000-000000000004', 100, 'RULES_SITE_REQUIREMENTS_E', NULL,
                                                                                                                                                                                                                   E'All improvements to the lot/space by Tenant, except natural lawn, which have been paid for by Tenant shall be the property of Tenant.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000104', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000110', '0199a001-0000-7000-8000-000000000004', 110, 'RULES_SITE_REQUIREMENTS_F', NULL,
                                                                                                                                                                                                                   E'The location of the mobile/manufactured home on each lot/space must be approved by the Landlord, to ensure compliance with governing codes regarding setbacks and spacing. The Landlord or its agent must be present when a home is being sited on the lot. Tenants are responsible for any damage to the Landlord''s or any other tenant''s property, landscaping, or fixtures by any person acting under Tenant''s direction, employ, invitation, or control.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000104', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000111', '0199a001-0000-7000-8000-000000000004', 120, 'RULES_UTILITIES', 'Utilities',
                                                                                                                                                                                                                   E'Utilities may be disconnected temporarily when required to make necessary repairs. There shall be NO offset in the financial obligations or rent due to a temporary suspension of utilities for repairs, alterations, and/or additions to any utility system. Tampering with, altering, impairing, hindering, or damaging community electrical, water, or sewer connections is strictly forbidden. Contact the Landlord''s agent in case of a problem. No posts of any kind are to be driven into the ground without consulting all utilities for the location of underground utilities. Tenant will be held responsible for any damage to utilities.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000112', '0199a001-0000-7000-8000-000000000004', 130, 'RULES_WATER', 'Water',
                                                                                                                                                                                                                   E'',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000113', '0199a001-0000-7000-8000-000000000004', 140, 'RULES_WATER_A', NULL,
                                                                                                                                                                                                                   E'Resident''s water lines must have a suitable check valve device to prevent water heaters from back-draining in the event that the water supply is interrupted.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000112', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000114', '0199a001-0000-7000-8000-000000000004', 150, 'RULES_WATER_B', NULL,
                                                                                                                                                                                                                   E'All outside faucets located on Tenant''s lot space must be winterized/insulated so that no damage occurs due to freezing. Failure to winterize outside water connections may result in breakage of or damage to the community water or irrigation systems. Tenant is responsible for all costs associated with repairs of outside connections provided to the lot space.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000112', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000115', '0199a001-0000-7000-8000-000000000004', 160, 'RULES_WATER_C', NULL,
                                                                                                                                                                                                                   E'<b>Wasteful water:</b> Each tenant is responsible for watering their lot and keeping the grass green. <b>Unless otherwise directed by management, watering of lawns or garden areas shall follow a daily even/odd rotation in line with the resident''s unit number. Units identified by letter shall be considered even or odd based on alphanumeric position (for example: A = 1, B = 2, C = 3, etc.).</b> However, if there is an excessive amount of standing water in the yard or water running down the road or ditch, Tenant will be subject to a Notice of Non-Compliance. <b>Washing of vehicles is not allowed in the community. Tenants found irrigating on unapproved days or washing vehicles will be issued a Notice of Non-Compliance.</b>',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000112', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000116', '0199a001-0000-7000-8000-000000000004', 170, 'RULES_SEPTIC_SEWER', 'Septic/Sewer',
                                                                                                                                                                                                                   E'The Tenant(s) is responsible for the pipes running from their house to the supplied connection at ground level. If anything clogs the line that is not the result of a damaged or defective buried line, it is Tenant''s responsibility to fix it or contract for services. Tenants will not be held responsible for damage resulting from normal wear and tear or from the Landlord''s failure to maintain or protect the utilities within its control. Any charges to Tenant for repairs will be reasonable, documented, and provided to Tenant on an itemized bill. Tenants may dispute such charges by emailing {{landlord.compliance_email}} or by mailing their dispute to <b>{{property.community_name}}</b>, {{landlord.address}}.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000117', '0199a001-0000-7000-8000-000000000004', 180, 'RULES_SEPTIC_ONSITE', NULL,
                                                                                                                                                                                                                   E'Homes with sub-metered water connections served by an <u>Onsite Septic System</u> or <u>Onsite Water System</u> will be limited to <b>nine thousand gallons (9,000 gal) per month.</b> Any tenant''s water use in excess of this amount on an onsite water system connection will be issued a notice to comply for excess water usage. After three notices to comply within one calendar year, tenants may be subject to RCW 59.20.080 and termination of the lease agreement. The cost of repairing any tenant-caused damage to the septic system from excessive usage or misuse will be passed on to Tenant.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000118', '0199a001-0000-7000-8000-000000000004', 190, 'RULES_SEPTIC_PUMPING', NULL,
                                                                                                                                                                                                                   E'Septic tanks are periodically inspected and pumped by Management approximately once every three years, or as needed. If more frequent pumping is required because of excessive water use (average water use is approximately 240 gallons per home per day) or the other abuses discussed above, the cost of the extra pumping may be charged to the Tenant(s) of that particular system.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000119', '0199a001-0000-7000-8000-000000000004', 200, 'RULES_HOME_REQUIREMENTS', 'Manufactured Home Requirements',
                                                                                                                                                                                                                   E'Manufactured homes must either be new when entering the Park or meet current code requirements. Tongues and/or towing devices must be removed or covered. The home must be set up under the proper permit of the local building department or jurisdiction and conform to that permit. Any improvements, additions, decks, or stairs must be preapproved in writing by the Landlord through a reasonable accommodation request and permitted by the local building department or jurisdiction. All materials, including paint, must match and/or complement existing mobile homes. Structures designed for temporary use (e.g., portable carports, day shades, and pavilions) may not be kept as, or used to replace or replicate, permanent structures. Portable structures must be removed at the end of the event, not to exceed 48 hours.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000120', '0199a001-0000-7000-8000-000000000004', 210, 'RULES_LANDSCAPING', 'Landscaping and Lot Maintenance',
                                                                                                                                                                                                                   E'Resident/Tenant shall maintain the landscaping and lawn on the resident''s lot in good condition. Lawns must be mowed, trimmed, watered, and fertilized on a regular basis, as conditions allow. The lot space is to be kept free of weeds and other noxious plants that tend to spread by root or seed. The lot must be sprayed as needed to control pests or disease. All dead or diseased plants or bushes must be removed and replaced with healthy plants. Landlord reserves the right to require the removal of any tree, bush, or shrub with a diameter greater than 4 inches, measured at the base, that affects any underground utilities. No burning of yard waste, refuse, or debris, and no open flames, are allowed on the lot space or in any common area. Any lawn or space not maintained by Tenant will be cared for by the Landlord, its agent, or a professional yard maintenance service. Any reasonable sum spent on landscaping will be charged to Tenant after notifying Tenant and allowing time to cure the violation.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000121', '0199a001-0000-7000-8000-000000000004', 220, 'RULES_APPEARANCE', 'Home and Space Appearance',
                                                                                                                                                                                                                   E'Tenant shall continuously maintain the exterior of the mobile/manufactured home to a high standard, presenting an eye-pleasing appearance, as conditions allow. All colors and finish materials shall be aesthetically appropriate. The home shall not be allowed to become unsightly, as solely determined by the Landlord/agent. It is the Landlord''s intent to maintain a mobile home community of high industry standards, which is to the direct benefit of all residents of the Park:',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000122', '0199a001-0000-7000-8000-000000000004', 230, 'RULES_APPEARANCE_A', NULL,
                                                                                                                                                                                                                   E'Resident shall keep and maintain the home and any tenant-owned accessory structures, including any tenant-owned carports, sheds, and storage units, washed and in good repair at all times, as conditions allow. Painted areas shall not be allowed to peel or become weather-beaten and shall be reasonably cared for. Any damaged portion of the home or accessory structures shall be promptly repaired, as conditions allow. Tenant/resident shall make reasonable efforts to re-roof, re-side, or re-paint the exterior as needed to maintain park standards.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000123', '0199a001-0000-7000-8000-000000000004', 240, 'RULES_APPEARANCE_B', NULL,
                                                                                                                                                                                                                   E'No fences are allowed without the prior written approval of the Landlord.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000124', '0199a001-0000-7000-8000-000000000004', 250, 'RULES_APPEARANCE_C', NULL,
                                                                                                                                                                                                                   E'All signs, including "for sale" signs, must have the prior approval of the Landlord, unless otherwise required by the codes, statutes, ordinances, and administrative rules applicable to the mobile home park.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000125', '0199a001-0000-7000-8000-000000000004', 260, 'RULES_APPEARANCE_D', NULL,
                                                                                                                                                                                                                   E'No furniture, other than standard lawn or patio furniture and barbecue grills, will be permitted on the patio, porch, or yard. <b>All other items shall be stored out of sight in the storage unit.</b> Garbage containers shall be stored out of sight except on pick-up day.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000126', '0199a001-0000-7000-8000-000000000004', 270, 'RULES_APPEARANCE_E', NULL,
                                                                                                                                                                                                                   E'Temporary use of tarps for roofs, porches, and other purposes such as water leaks shall not extend past 30 days. Repairs must be made and the tarps removed within that time frame.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000127', '0199a001-0000-7000-8000-000000000004', 280, 'RULES_APPEARANCE_F', NULL,
                                                                                                                                                                                                                   E'While a resident is on vacation or away from the Park for an extended period of time for any reason, it is the responsibility of Tenant to arrange for the maintenance of the home and lot space in their absence. Residents are encouraged to notify the manager of the dates they will be gone and where they, or the party responsible, can be contacted.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000128', '0199a001-0000-7000-8000-000000000004', 290, 'RULES_APPEARANCE_G', NULL,
                                                                                                                                                                                                                   E'If any of the HOME AND SPACE APPEARANCE rules are broken, the tenant(s) will receive a notice to comply.',
                                                                                                                                                                                                                   '0199a002-0000-7000-8000-000000000121', NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000129', '0199a001-0000-7000-8000-000000000004', 300, 'RULES_BEHAVIOR', 'Behavior',
                                                                                                                                                                                                                   E'Activities which unreasonably disturb or interfere with the peaceful enjoyment of any part of the Park shall not be permitted. Activities that violate any federal, state, or local statute, ordinance, regulation, or rule shall not be permitted by Tenant(s), Resident(s), or their guest(s). The use of firearms or fireworks within the Park is prohibited. Abuse of alcohol or drugs will not be tolerated. Drunkenness or immoral conduct will not be tolerated. Any lewd, vulgar, obscene, and/or threatening conduct toward another person by any tenant/resident of the park will not be tolerated and will be immediately reported to the police. Pursuant to RCW 69.51A, the cultivation or production of marijuana or marijuana concentrates is not allowed outside the home or inside any accessory structure located within the community. The Landlord/agent has the right to begin an eviction if the police have been called to Tenant''s residence three times in a one-year period for disturbance or improper conduct.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 69.51A', 'The 2024 packet cited RCW 69.15A, which does not exist; changed to RCW 69.51A -- confirm the intended citation', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000130', '0199a001-0000-7000-8000-000000000004', 310, 'RULES_NOISE', 'Noise',
                                                                                                                                                                                                                   E'Excessive or disturbing noises are not permitted at any time, including from TVs, radios, stereos, etc. No lawn mowing will be permitted between 9:00 PM and 7:00 AM. Please be especially considerate between the hours of 9:00 PM and 7:00 AM, which are hereby designated quiet hours. Consideration of your neighbors is always required. Lewd, vulgar, harassing, or threatening language and/or conduct is prohibited.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000131', '0199a001-0000-7000-8000-000000000004', 320, 'RULES_SOLICITATION', 'Solicitation',
                                                                                                                                                                                                                   E'No business, commercial enterprise, or door-to-door solicitation shall be permitted within the park. Door-to-door solicitation does not include public officials, housing and low-income assistance organizations, or candidates for public office meeting with or distributing information to tenants in accordance with RCW 59.20.070.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.070', 'The 2024 packet said "subsection (3) or (4) of this section", copied from the statute; it now names it', '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000132', '0199a001-0000-7000-8000-000000000004', 330, 'RULES_STORAGE', 'Storage',
                                                                                                                                                                                                                   E'Storage will not be allowed beneath the mobile home or porch. No rubbish will be allowed to accumulate. All stored items are to be placed in approved storage sheds. Tenant-owned storage sheds, and all other structures located on Tenant''s mobile home lot, must be clean and maintained in accordance with park standards. All tenants are reasonably required to maintain their homes and tenant-owned accessory structures, including any tenant-owned carports or storage units, clean and in good repair at all times. (See Rule {{ref:0199a002-0000-7000-8000-000000000122}}.)\n\nIf you have any questions regarding whether your structure is tenant- or park-owned, please contact {{landlord.compliance_email}} or mail your communication to <b>{{property.community_name}}</b>, {{landlord.address}}. You may also contact us regarding any repairs to park-owned structures or reasonable accommodation requests related to repairs of tenant-owned structures.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000133', '0199a001-0000-7000-8000-000000000004', 340, 'RULES_GUESTS', 'Guests',
                                                                                                                                                                                                                   E'Residents are fully responsible for their guests and must accompany them throughout the park. Residents must inform their guest(s) of the park rules and regulations and vehicle rules, which are for the safety of all. Residents are responsible for any children visiting them in the park. Guests'' children shall play only in the resident''s space and shall not disturb other residents. Guest parking should be for passenger cars or pickups only and shall not obstruct or violate other residents'' parking or property rights. Any guest vehicle parked in excess of 36 hours must be identified by placement of the resident''s name and space number where the guest is visiting, to prevent towing or impounding. Residents shall receive a notice to comply listing each violation of the provisions of the vehicle agreement or parking rules relating to guest parking. Guest parking fees shall be due and payable to the Landlord on the next month''s rent due date. Resident hereby authorizes the Landlord or its agent to tow or impound, at the resident''s expense, any vehicle of a resident''s guest which is not parked in accordance with the terms of this agreement, provided that the Landlord or its agent first attempts to notify the owner of the vehicle or the resident. In the event that a resident has relatives or other guests visiting, the temporary resident shall not visit more than fifteen (15) days in a 60-day period. Guests staying over fifteen (15) days during a sixty (60) day period must be preapproved in writing by the Landlord/agent and are subject to a daily guest occupancy fee of $5.00 per day. Daily babysitting or caretaking is not allowed without a reasonable accommodation request. Resident is responsible for any damage to the Landlord''s or any other resident''s property, landscaping, or fixtures by any person acting under the resident''s direction, employ, invitation, or control. If more than 6 guests are visiting, it is the Tenant(s)'' responsibility to obtain a portable toilet, which can be rented from a local septic company.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000134', '0199a001-0000-7000-8000-000000000004', 350, 'RULES_VEHICLES', 'Vehicles',
                                                                                                                                                                                                                   E'Applications for permission to park a vehicle in the Mobile Home Park shall be made on the "Reasonable Accommodation" form and, if approved, shall become an addendum to the rental agreement. No more than {{term.allowed_cars_in_words}} ({{term.allowed_cars}}) vehicles shall be regularly kept at a lot by a resident unless approved by the Landlord/agent. Only passenger cars, quiet motorcycles, and pickup trucks that are operable and licensed with current tabs are allowed at the lot. Boats, RVs, trailers, snowmobiles, etc. shall be stored elsewhere at the resident''s expense and are not allowed in the park, for safety and appearance reasons. There will be no on-street parking. ONLY minor repair and maintenance will be permitted. No oils, fuels, antifreeze, or other fluids shall be disposed of in any sanitary sewer or storm drain or on the ground. No major or extended repair or storage is permitted. No vehicles up on ramps or blocks. Vehicles that are not in reasonable or constant use must be stored elsewhere. The speed limit inside the park is 10 mph unless otherwise posted.\n\nA notice to comply will be issued for not complying with the rules and regulations and vehicle agreements. For additional rules on vehicles, refer to the Vehicle Agreement.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000135', '0199a001-0000-7000-8000-000000000004', 360, 'RULES_CHILDREN', NULL,
                                                                                                                                                                                                                   E'Parents can be held responsible and accountable for the acts of their children, household members, and guests. No resident is allowed to trespass on another resident''s space. Parents are responsible for keeping their children away from the mailboxes. Trampolines, swimming pools over 20 gallons, and play structures, except those approved through reasonable accommodation, are NOT allowed in the community.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000136', '0199a001-0000-7000-8000-000000000004', 370, 'RULES_PETS', 'Pets',
                                                                                                                                                                                                                   E'Written prior acceptance must be obtained if you wish to keep a pet in the park. Applications for permission shall be made on the "Pet Agreement" form and, if approved, shall become an addendum to the rental agreement. No more than {{term.allowed_pets_in_words}} ({{term.allowed_pets}}) pets shall be allowed. Cats will be permitted only if they are inside cats and must be confined in the house or on a leash at all times. Pets over 40 pounds fully grown are not allowed. No pet is allowed to run free off leash, cause a disturbance to any other resident, or cause a hazard in the park. Any household pet which interferes with the peaceful enjoyment of the park, in the opinion of the Landlord or its agent, shall be promptly removed from the park upon request. If any of the pet rules are broken, the tenant(s) will receive a notice to comply. After three notices to comply within one calendar year, tenants may be subject to RCW 59.20.080 and termination of the lease agreement.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000137', '0199a001-0000-7000-8000-000000000004', 380, 'RULES_OCCUPANTS', 'Occupants',
                                                                                                                                                                                                                   E'Only the residents and people specifically named in the Rental Agreement shall reside permanently on the leased lot/space. Up to 2 occupants are allowed for each bedroom in the home, as designed by the manufacturer, plus 1 additional occupant at the base rent. The monthly rent will increase by 20% of the base rent for each additional occupant unless an exception is given in writing by the Landlord. No home shall house more than two (2) people per bedroom plus 1. All persons 18 years of age or older moving into the park must be screened and approved by the Landlord. Any occupant vacating residency at a lot must apply for occupancy if they wish to return to occupy it in the future.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000138', '0199a001-0000-7000-8000-000000000004', 390, 'RULES_SALE_NOTICE', NULL,
                                                                                                                                                                                                                   E'Tenant/Resident will advise the Landlord or its agent of any plans to sell or transfer ownership of their mobile/manufactured home. Resident may NOT represent to the buyer or transferee that they may retain the lot/space without first obtaining the written approval of the Landlord or its agent. Any transfer of ownership interest and/or lot tenancy must be performed in accordance with the Washington Manufactured/Mobile Home Landlord-Tenant Act, RCW 59.20 et seq.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000139', '0199a001-0000-7000-8000-000000000004', 400, 'RULES_COMPLY_WITH_LAW', NULL,
                                                                                                                                                                                                                   E'Resident agrees to comply with all state, county, and city laws affecting this home, space, or improvements.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000140', '0199a001-0000-7000-8000-000000000004', 410, 'RULES_RESPONSIBILITY', 'Responsibility',
                                                                                                                                                                                                                   E'Failure to occupy the mobile/manufactured home does not relieve the Tenant/Resident of any responsibilities set forth in the Rental Agreement or the Park Rules and Regulations.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000141', '0199a001-0000-7000-8000-000000000004', 420, 'RULES_STRUCTURES', NULL,
                                                                                                                                                                                                                   E'Trampolines, swimming pools over 20 gallons, and play structures, except those approved through reasonable accommodation, are NOT allowed in the community.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000142', '0199a001-0000-7000-8000-000000000004', 430, 'RULES_APPROVALS', 'Approvals',
                                                                                                                                                                                                                   E'Requests for reasonable accommodation under the park rules, or for any modification of or addition to the lot space where the Landlord''s approval or consent is required under these rules, shall be made in writing, with such information as the Landlord may reasonably require to be sufficiently informed to give or refuse approval. The Landlord has fourteen (14) days from receipt of any request within which to notify the Tenant/Resident of its decision to accept or deny the request. Requests can be sent to {{landlord.compliance_email}} or mailed to <b>{{property.community_name}}</b>, {{landlord.address}}.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000143', '0199a001-0000-7000-8000-000000000004', 440, 'RULES_CLOSING', NULL,
                                                                                                                                                                                                                   E'<b>THE RULES AND REGULATIONS ARE WRITTEN FOR YOUR GENERAL WELFARE, SAFETY, AND ENJOYMENT. YOUR COMPLIANCE IS NECESSARY IN ORDER TO MAINTAIN THE DESIRED HIGH COMMUNITY STANDARDS AT {{property.community_name}}.</b> These Rules are subject to amendment and/or change upon thirty (30) days'' notice by the Landlord/agent.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000144', '0199a001-0000-7000-8000-000000000004', 450, 'RULES_SIGNATURE', NULL,
                                                                                                                                                                                                                   E'I/We have read and initialed each page of the Rules and Regulations, and I/We UNDERSTOOD AND AGREED TO them this <rule w="6"> day of <rule w="18">, {{instrument.execution_year}}, as signed below.\n\n{{#each tenancy.signers}}<rule w="42">\n{{signer.name}}, Tenant\n\n{{/each}}<rule w="42">\nOwner/Agent for {{landlord.name}}\nIts: Manager',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000004', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002');


-- ── Vehicle Agreement ──
INSERT INTO template_clause (uuid, section, ordinal, clause_key, title, body, parent, variant_of, numbered, requires_next, style, condition_field, condition_values, required, statute_ref, note, created_by) VALUES
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000145', '0199a001-0000-7000-8000-000000000005', 10, 'VEHICLE_HEADER', NULL,
                                                                                                                                                                                                                   E'{{property.community_name}}\n\nAddendum to Park Rules and Regulations',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000002', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000146', '0199a001-0000-7000-8000-000000000005', 20, 'VEHICLE_PARTIES', NULL,
                                                                                                                                                                                                                   E'This agreement is attached to and forms a part of the Rental Agreement between the Landlord of <b>{{property.community_name}}</b> and <b>{{tenancy.tenant_names}}</b>, Tenant(s).',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000147', '0199a001-0000-7000-8000-000000000005', 30, 'VEHICLE_SUBSTANCES', NULL,
                                                                                                                                                                                                                   E'No motor oil or any other caustic, non-biodegradable substance shall be deposited in any street, drain, or sewer system or on the grounds within the community. Homeowner shall be responsible for any and all fines and for the cost of cleaning up any caustic or non-biodegradable substance deposited by Homeowner in the community. Propane tanks larger than five gallons are not allowed in the community, except those attached to and used exclusively for the manufactured home.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000148', '0199a001-0000-7000-8000-000000000005', 40, 'VEHICLE_TWO_ALLOWED', NULL,
                                                                                                                                                                                                                   E'Homeowner is allowed to have no more than {{term.allowed_cars_in_words}} ({{term.allowed_cars}}) vehicles at the lot; when vehicles are not in use, any others must be parked elsewhere at Homeowner''s expense.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000149', '0199a001-0000-7000-8000-000000000005', 50, 'VEHICLE_EXTRA_FEE', NULL,
                                                                                                                                                                                                                   E'Homeowners may request approval from the Landlord/agent to keep more than {{term.allowed_cars_in_words}} vehicles. Any approval given will be conditional. Homeowner will be charged <u><b>{{term.car_fee}}</b></u> per month per extra vehicle if approved by the Landlord/agent through a reasonable accommodation request. NO MORE than {{term.cars_max}} vehicles will be allowed per lot.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000150', '0199a001-0000-7000-8000-000000000005', 60, 'VEHICLE_CONDITION', NULL,
                                                                                                                                                                                                                   E'Vehicles dripping oil, fluid, or any other lubricant or chemical must be removed from the community until they are repaired. Homeowner is responsible for immediately cleaning up any oil, fluid, lubricant, or chemical from the driveway and street. Landlord may require that any vehicle, including vehicles owned by homeowners, not be allowed to enter or remain in the community if, in Landlord''s opinion, the vehicle (a) is not properly maintained, (b) constitutes a hazard to homeowners, or (c) is in such dilapidated condition that it detracts from the appearance of the community. If Landlord intends to remove a vehicle from the community under this rule, it will give 24 hours'' notice to the homeowner responsible for the vehicle. If the vehicle is not removed from the community within 24 hours, a towing company will, at the Landlord/agent''s request, tow the vehicle from the community at the risk and expense of the homeowner. In the alternative, the Landlord/agent may give notice to the homeowner to remove the vehicle from the community, and failure to do so shall serve as a basis for termination of the homeowner''s tenancy.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000151', '0199a001-0000-7000-8000-000000000005', 70, 'VEHICLE_COMMERCIAL', NULL,
                                                                                                                                                                                                                   E'Homeowner is not allowed to park, or allow others to park, in the community any commercial vehicles or equipment (other than those temporarily present for the purpose of providing a service to Homeowner), vehicles lacking current license tabs, or inoperable vehicles.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000152', '0199a001-0000-7000-8000-000000000005', 80, 'VEHICLE_GUEST_BLOCKING', NULL,
                                                                                                                                                                                                                   E'Homeowner and guests must ensure that guests'' cars are parked in a location that does not block any neighbor''s access or restrict traffic flow within the community.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000153', '0199a001-0000-7000-8000-000000000005', 90, 'VEHICLE_UNAUTHORIZED', NULL,
                                                                                                                                                                                                                   E'Parking in park streets, on other neighbors'' lots, on grass yards, or in unauthorized parking areas by guests or Tenant is NOT allowed and is subject to towing at the owner''s expense.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000154', '0199a001-0000-7000-8000-000000000005', 100, 'VEHICLE_GVWR', NULL,
                                                                                                                                                                                                                   E'Approval of the owner/agent must be obtained before bringing any vehicle with a GVWR larger than 10,000 lbs. single axle into the community. Trucks of 14,000 lbs. GVWR or larger will not be allowed to park overnight on a homeowner''s lot.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000155', '0199a001-0000-7000-8000-000000000005', 110, 'VEHICLE_TOWING', NULL,
                                                                                                                                                                                                                   E'Vehicles parked in violation of the Vehicle Agreement will be towed away and impounded at the homeowner''s expense.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000156', '0199a001-0000-7000-8000-000000000005', 120, 'VEHICLE_SPEED_LIMIT', NULL,
                                                                                                                                                                                                                   E'Unless otherwise posted, the speed limit within the community for all vehicles is ten (10) miles per hour, and vehicles must be reasonably paced under the circumstances to avoid risk of accident or injury. Violations may be issued based upon a visual estimate of excessive speed, without radar or pacing.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000157', '0199a001-0000-7000-8000-000000000005', 130, 'VEHICLE_RV_STORAGE', NULL,
                                                                                                                                                                                                                   E'Motor homes, campers, trailers, snowmobiles, retired commercial vehicles, and other recreational vehicles are not allowed to be stored on the homeowner''s lot without permission from the Landlord/agent.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000158', '0199a001-0000-7000-8000-000000000005', 140, 'VEHICLE_VACANT_LOTS', NULL,
                                                                                                                                                                                                                   E'Driveways of vacant lots may not be used as guest or overflow parking without approval from the Landlord/agent.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000159', '0199a001-0000-7000-8000-000000000005', 150, 'VEHICLE_LOUD', NULL,
                                                                                                                                                                                                                   E'Loud motor vehicles may not operate in the community at any time.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000160', '0199a001-0000-7000-8000-000000000005', 160, 'VEHICLE_REPAIRS', NULL,
                                                                                                                                                                                                                   E'Homeowners are not allowed to overhaul or perform general maintenance of vehicles on their lot or in their driveway. No repair of automobile motors, engines, trailers, boats, or other similar equipment will be made within the community. Oil changes or other routine vehicle maintenance are not an exception to this rule.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000161', '0199a001-0000-7000-8000-000000000005', 170, 'VEHICLE_GRASS_STREET', NULL,
                                                                                                                                                                                                                   E'No parking on grass or on the streets at any time, unless approved through a reasonable accommodation request.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000162', '0199a001-0000-7000-8000-000000000005', 180, 'VEHICLE_GUEST_36_HOURS', NULL,
                                                                                                                                                                                                                   E'Any guest vehicle parked in excess of thirty-six (36) hours must be properly identified by placement of the tenant''s name and lot number where the guest is visiting, to prevent impound or towing.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000163', '0199a001-0000-7000-8000-000000000005', 190, 'VEHICLE_BASE_ALLOWANCE', NULL,
                                                                                                                                                                                                                   E'Tenant will be allowed to have {{term.allowed_cars}} vehicles at the base lot rent. There will be an additional fee of {{term.car_fee_in_words}} <b>({{term.car_fee}})</b> per month for each additional vehicle, up to a total of {{term.cars_max}} vehicles. Any additional vehicles must fit into the driveway provided with the lot space.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000164', '0199a001-0000-7000-8000-000000000005', 200, 'VEHICLE_NOTICE_TO_COMPLY', NULL,
                                                                                                                                                                                                                   E'A notice to comply will be issued for not complying with the rules and regulations and vehicle agreements.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000165', '0199a001-0000-7000-8000-000000000005', 210, 'VEHICLE_SUMMARY', NULL,
                                                                                                                                                                                                                   E'<b>Up to {{term.allowed_cars_in_words}} ({{term.allowed_cars}}) vehicles shall be permitted at any home at any time. Each additional vehicle, approved through a reasonable accommodation request, will be charged {{term.car_fee}} per month. NO more than {{term.cars_max}} vehicles per lot.</b>',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000166', '0199a001-0000-7000-8000-000000000005', 220, 'VEHICLE_LIST', NULL,
                                                                                                                                                                                                                   E'<b>LIST OF VEHICLES:</b>\n\nMake: <rule w="18">  Model: <rule w="14">  Year: <rule w="8">  Plate #: <rule w="14">\n\nMake: <rule w="18">  Model: <rule w="14">  Year: <rule w="8">  Plate #: <rule w="14">\n\nMake: <rule w="18">  Model: <rule w="14">  Year: <rule w="8">  Plate #: <rule w="14">\n\nMake: <rule w="18">  Model: <rule w="14">  Year: <rule w="8">  Plate #: <rule w="14">',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000167', '0199a001-0000-7000-8000-000000000005', 230, 'VEHICLE_SIGNATURE', NULL,
                                                                                                                                                                                                                   E'UNDERSTOOD AND AGREED TO this <rule w="6"> day of <rule w="18">, {{instrument.execution_year}}, as signed below.\n\n{{#each tenancy.signers}}<rule w="42">\n{{signer.name}}, Tenant\n\n{{/each}}<rule w="42">\nOwner/Agent for {{landlord.name}}\nIts: Manager',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000004', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002');


-- ── Pet Agreement ──
INSERT INTO template_clause (uuid, section, ordinal, clause_key, title, body, parent, variant_of, numbered, requires_next, style, condition_field, condition_values, required, statute_ref, note, created_by) VALUES
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000168', '0199a001-0000-7000-8000-000000000006', 10, 'PET_HEADER', NULL,
                                                                                                                                                                                                                   E'{{property.community_name}}\n\nAddendum to Park Rules and Regulations',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000002', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000169', '0199a001-0000-7000-8000-000000000006', 20, 'PET_PARTIES', NULL,
                                                                                                                                                                                                                   E'This agreement is attached to and forms a part of the Rental Agreement between the Landlord, <b>{{property.community_name}}</b>, and <b>{{tenancy.tenant_names}}</b>, Tenant(s).',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000170', '0199a001-0000-7000-8000-000000000006', 30, 'PET_LIMIT', NULL,
                                                                                                                                                                                                                   E'<b>No more than {{term.allowed_pets_in_words}} ({{term.allowed_pets}}) pets shall be permitted in any home at any time.</b>',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000171', '0199a001-0000-7000-8000-000000000006', 40, 'PET_DESCRIPTION', NULL,
                                                                                                                                                                                                                   E'Tenant(s) desire to keep a pet, described as follows, on the premises they occupy under the Rental Agreement above.\n\nDog <rule w="6">  Cat <rule w="6">  Other (please specify): <rule w="30">\n\nBreed: <rule w="20">  Age: <rule w="10">  Weight: <rule w="10">',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000172', '0199a001-0000-7000-8000-000000000006', 50, 'PET_PREAMBLE', NULL,
                                                                                                                                                                                                                   E'Because the Rental Agreement specifically prohibits keeping a pet without the Landlord''s permission, Tenant(s) agrees to the following terms and conditions in exchange for this addendum to the Rental Agreement:',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000173', '0199a001-0000-7000-8000-000000000006', 60, 'PET_RULE_1', NULL,
                                                                                                                                                                                                                   E'The pet must be under control at all times (in the home, on a leash, or within an <u>invisible</u> fence).',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000174', '0199a001-0000-7000-8000-000000000006', 70, 'PET_RULE_2', NULL,
                                                                                                                                                                                                                   E'Tenant agrees that the authorized pet(s) listed in this addendum shall not be left outdoors, either tethered or roaming, at any time while unattended or when the occupants are not at home.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000175', '0199a001-0000-7000-8000-000000000006', 80, 'PET_RULE_3', NULL,
                                                                                                                                                                                                                   E'The pet is to be aired on Tenant''s lot only, and the waste is to be picked up daily and disposed of properly.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000176', '0199a001-0000-7000-8000-000000000006', 90, 'PET_RULE_4', NULL,
                                                                                                                                                                                                                   E'Tenant agrees to keep their pet from causing any annoyance or discomfort to others and will immediately remedy any complaint made through the Landlord. Animals shall not display or engage in threatening or hostile behavior, including but not limited to biting, growling, lunging, barking, whining, or other disturbing behavior.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000177', '0199a001-0000-7000-8000-000000000006', 100, 'PET_RULE_5', NULL,
                                                                                                                                                                                                                   E'There is no feeding of pets outdoors. Feeding of wild or stray animals is not allowed.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000178', '0199a001-0000-7000-8000-000000000006', 110, 'PET_RULE_6', NULL,
                                                                                                                                                                                                                   E'Absolutely no breeding or reproduction of pets will be allowed. Pet offspring must be removed from the premises within eight (8) weeks of their birth.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000179', '0199a001-0000-7000-8000-000000000006', 120, 'PET_RULE_7', NULL,
                                                                                                                                                                                                                   E'The Landlord/agent reserves the right to charge for damages when Tenant vacates.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000180', '0199a001-0000-7000-8000-000000000006', 130, 'PET_RULE_8', NULL,
                                                                                                                                                                                                                   E'The tenant(s) agrees that the Landlord reserves the right to revoke permission to keep the pet should Tenant break this agreement in any way.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000181', '0199a001-0000-7000-8000-000000000006', 140, 'PET_RULE_9', NULL,
                                                                                                                                                                                                                   E'NO FARM or LIVESTOCK animals on the premises of the community.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000182', '0199a001-0000-7000-8000-000000000006', 150, 'PET_RULE_10', NULL,
                                                                                                                                                                                                                   E'If any of the pet rules are broken, the tenant(s) will receive a notice to comply. After three notices to comply within one calendar year, Tenant may be subject to RCW 59.20.080 and termination of the lease agreement.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, 'RCW 59.20.080', NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000183', '0199a001-0000-7000-8000-000000000006', 160, 'PET_RULE_11', NULL,
                                                                                                                                                                                                                   E'Abandoned and/or neglected animals may be removed in case of emergency and taken to a shelter.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000184', '0199a001-0000-7000-8000-000000000006', 170, 'PET_RULE_12', NULL,
                                                                                                                                                                                                                   E'Service animals must abide by all of the above rules.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000185', '0199a001-0000-7000-8000-000000000006', 180, 'PET_RULE_13', NULL,
                                                                                                                                                                                                                   E'Only small to medium-sized dogs and cats are allowed in the park (<b>under 40 lbs. fully grown</b>), unless the pet was grandfathered in at the time the community was purchased.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000186', '0199a001-0000-7000-8000-000000000006', 190, 'PET_RULE_14', NULL,
                                                                                                                                                                                                                   E'Any animal, regardless of status or purpose, that poses a risk or an unreasonable nuisance to the community may be subject to a notice to comply or removal action.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000187', '0199a001-0000-7000-8000-000000000006', 200, 'PET_RULE_15', NULL,
                                                                                                                                                                                                                   E'Tenants have the right to dispute any pet-related violation before any penalty or removal action is taken.',
                                                                                                                                                                                                                   NULL, NULL, TRUE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000188', '0199a001-0000-7000-8000-000000000006', 210, 'PET_SIGNATURE', NULL,
