-- ── Septic/Sewer System Care and Maintenance Addendum ──
INSERT INTO template_clause (uuid, section, ordinal, clause_key, title, body, parent, variant_of, numbered, requires_next, style, condition_field, condition_values, required, statute_ref, note, created_by) VALUES
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000189', '0199a001-0000-7000-8000-000000000007', 10, 'SEPTIC_HEADER', NULL,
                                                                                                                                                                                                                   E'{{property.community_name}}',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000002', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000190', '0199a001-0000-7000-8000-000000000007', 20, 'SEPTIC_PROHIBITED', NULL,
                                                                                                                                                                                                                   E'<u><b>The following are not to be used or disposed of in your septic or sewer system:</b></u>\n# Grease, fats, oils, pesticides, herbicides, or any other toxins.\n# Paints, household chemicals, or automobile fluids.\n# Citrus products (oranges, lemons, grapefruits, etc.).\n# Non-biodegradable items such as cigarette butts, disposable diapers, baby wipes, toilet cleaning wipes, feminine hygiene products, condoms, hair, coffee grounds, rags, paper towels, bandages, clothing, toys, toiletry articles, etc.\n# Additives advertised for septic systems. They do more harm to the drain field than good to the tank.\n# Home brewery waste, strong medicines, and antibiotics. Antibacterial soaps and wipes should also be avoided.\n# Strong disinfectants or bleaches.\n# Laundry and cleaning products such as Lysol, Pine-Sol, Murphy''s Oil Soap, Downy, Snuggle, and water softeners.\n# Drain cleaners such as Drano.\n# Mop water.\n# Garbage disposals, which are prohibited.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000191', '0199a001-0000-7000-8000-000000000007', 30, 'SEPTIC_ACCEPTABLE', NULL,
                                                                                                                                                                                                                   E'<u><b>The following practices and products are acceptable:</b></u>\n# Spread your laundry loads out over the week, choosing one day each week to do all the bleaching. Excessive water discharge into the system is known as hydraulic overload and is the number one cause of drain field failure. Just one cup of bleach in a 1,000-gallon tank kills 80 percent of the tank for up to 72 hours, so bleaching on one day gives the tank time to recover.\n# Recommended detergents are liquid, low-sudsing, low-phosphate, and biodegradable, such as those with washing soda ingredients (examples: Gain, Dash, Arm & Hammer, Fresh Start, and Bright). Use fabric softener dryer sheets instead of liquids in the washer.\n# Recommended cleaning products are liquid, non-chlorine, biodegradable, and non-toxic, such as Ivory and Sunlight, or powdered cleansers such as Biz, Comet, and baking soda.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000192', '0199a001-0000-7000-8000-000000000007', 40, 'SEPTIC_OWNERSHIP', NULL,
                                                                                                                                                                                                                   E'<u><b>The septic system is the property of the Landlord. Landlord is responsible for maintaining it in good working order. Landlord does not authorize Tenant to perform maintenance of any sort on the septic system. Tenants are not to tamper with septic tank lids, risers, cleanouts, or filters. Tenant is to take precautions to prevent anyone from driving on the septic tank lids, cleanouts, or drain fields, or damaging them in any way.</b></u>',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000193', '0199a001-0000-7000-8000-000000000007', 50, 'SEPTIC_CHARGES', NULL,
                                                                                                                                                                                                                   E'Failure to follow these guidelines will result in clogs, sluggish draining, system failure, and/or sewage spillage. Tenants hereby agree to follow these guidelines. If Tenant neglects or abuses their septic system, resulting in any of the above conditions, Landlord will immediately cure the problem and Tenant will be charged accordingly. If more than one tenant is on the same system, the charges will be divided among them equally. Tenant agrees to pay such charges on or before the next rent due date. Failure to pay the charges in addition to the following month''s rent is grounds for eviction. Tenant further agrees that said charges will be paid first, before any funds are applied toward rent.',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, '00000000-0000-7000-8000-000000000002'),
                                                                                                                                                                                                                  ('0199a002-0000-7000-8000-000000000194', '0199a001-0000-7000-8000-000000000007', 60, 'SEPTIC_SIGNATURE', NULL,
                                                                                                                                                                                                                   E'UNDERSTOOD AND AGREED TO this <rule w="6"> day of <rule w="18">, {{instrument.execution_year}}, as signed below.\n\n{{#each tenancy.signers}}<rule w="42">\n{{signer.name}}, Tenant\n\n{{/each}}<rule w="42">\nOwner/Agent for {{landlord.name}}\nIts: Manager',
                                                                                                                                                                                                                   NULL, NULL, FALSE, NULL, '0199a003-0000-7000-8000-000000000004', NULL, NULL, TRUE, NULL, NULL, '00000000-0000-7000-8000-000000000002');
